//! Emission of one JS module: type classes, then functions.
//!
//! Function bodies are emitted from Core's ANF directly. Join points become either labelled
//! blocks / `for (;;)` loops (when every jump to them happens in the same JS function) or local
//! arrow functions (when a jump happens inside a continuation closure). See ABI.md §1.

use std::cell::RefCell;
use std::collections::{BTreeSet, HashMap, HashSet};
use std::fmt::Write;

use sakura_core::builtins::{self, Abi};
use sakura_core::opt::handlers::{self, Bound};
use sakura_core::opt::owned;
use sakura_core::*;

use crate::direct::{self, Closures};
use crate::sourcemap::{self, Mapping};
use crate::{Cx, RESERVED, RUNTIME_FILE, ident, js_string, module_path};

pub(crate) fn module(cx: &Cx, module: &str) -> (String, String) {
    let mut w = W {
        out: String::new(),
        line: 0,
        depth: 0,
        maps: Vec::new(),
        pending: None,
        cx,
    };
    let ns = RefCell::new(BTreeSet::new());
    let pool = Pool {
        site_base: cx.sites.get(),
        ..Pool::default()
    };
    for (i, t) in cx.m.types.iter().enumerate() {
        if t.module == module && t.builtin.is_none() {
            type_class(&mut w, TypeId(i as u32));
        }
    }
    for r in &cx.m.refinements {
        if r.module == module {
            w.line(&format!(
                "$rt.refined({}, {}, {}, {});",
                js_string(&r.qualified_name()),
                js_string(&r.name),
                schema(cx.m, &r.base),
                cx.def_names[r.check.index()]
            ));
        }
    }
    let module_defs: Vec<&str> =
        cx.m.defs
            .iter()
            .enumerate()
            .filter(|(_, d)| d.module == module)
            .map(|(i, _)| cx.def_names[i].as_str())
            .collect();
    for (i, d) in cx.m.defs.iter().enumerate() {
        if d.module == module {
            let id = DefId(i as u32);
            if cx.direct.direct(id) {
                FnEmit::new(cx, id, module, &module_defs, Mode::Direct, &ns, &pool).def(&mut w);
                if cx.summaries[i].consumes.is_some() {
                    let mut e = FnEmit::new(cx, id, module, &module_defs, Mode::Direct, &ns, &pool);
                    e.owned_entry();
                    e.def(&mut w);
                }
            }
            FnEmit::new(cx, id, module, &module_defs, Mode::Cps, &ns, &pool).def(&mut w);
        }
    }

    let path = module_path(module);
    let up = "../".repeat(path.matches('/').count());
    let rel = |p: &str| {
        if up.is_empty() {
            format!("./{p}")
        } else {
            format!("{up}{p}")
        }
    };
    let mut head = format!(
        "// Generated by sakura from module {module}. Do not edit.\nimport * as $rt from \"{}\";\n",
        rel(RUNTIME_FILE)
    );
    for other in ns.borrow().iter() {
        let _ = writeln!(
            head,
            "import * as {} from \"{}\";",
            ns_name(other),
            rel(&module_path(other))
        );
    }
    head.push_str("const { G: $G, LIMIT: $L, bounce: $b, ret: $ret, T: $T, TRACE: $tr } = $rt;\n");
    for (i, lit) in pool.lits.borrow().iter().enumerate() {
        let _ = writeln!(head, "const $c{i} = {lit};");
    }
    let sites = pool.sites.borrow();
    if !sites.is_empty() {
        let _ = writeln!(
            head,
            "$rt.sites({}, [{}]);",
            pool.site_base,
            sites.join(", ")
        );
        cx.sites.set(pool.site_base + sites.len() as u32);
    }
    head.push('\n');
    let shift = head.matches('\n').count() as u32;
    let file = path.rsplit('/').next().unwrap_or(&path).to_owned();
    let maps = w
        .maps
        .iter()
        .map(|m| Mapping {
            gen_line: m.gen_line + shift,
            ..*m
        })
        .collect();
    let map = sourcemap::render(&file, &cx.sources, maps);
    let text = format!("{head}{}//# sourceMappingURL={file}.map\n", w.out);
    (text, map)
}

/// Module-level constants (schemas, source spans), deduplicated: `$c0`, `$c1`, …; and the
/// module's call sites for contract blame, numbered program-wide from `site_base` (ABI.md §5).
#[derive(Default)]
struct Pool {
    lits: RefCell<Vec<String>>,
    index: RefCell<HashMap<String, usize>>,
    site_base: u32,
    /// Pooled span constants, in site order.
    sites: RefCell<Vec<String>>,
    site_index: RefCell<HashMap<String, u32>>,
}

impl Pool {
    fn get(&self, lit: String) -> String {
        if let Some(&i) = self.index.borrow().get(&lit) {
            return format!("$c{i}");
        }
        let mut lits = self.lits.borrow_mut();
        lits.push(lit.clone());
        let i = lits.len() - 1;
        self.index.borrow_mut().insert(lit, i);
        format!("$c{i}")
    }

    /// The program-wide site number of a pooled span constant.
    fn site(&self, span: String) -> u32 {
        let mut sites = self.sites.borrow_mut();
        *self
            .site_index
            .borrow_mut()
            .entry(span)
            .or_insert_with_key(|span| {
                sites.push(span.clone());
                self.site_base + sites.len() as u32 - 1
            })
    }
}

fn ns_name(module: &str) -> String {
    format!("${}", ident(&module.replace("::", "_").replace('/', "_")))
}

struct W<'c> {
    out: String,
    line: u32,
    depth: usize,
    maps: Vec<Mapping>,
    pending: Option<Pos>,
    cx: &'c Cx<'c>,
}

impl W<'_> {
    fn line(&mut self, s: &str) {
        if let Some(pos) = self.pending.take()
            && let Some((source, ix)) = self.cx.lines.get(&pos.file)
        {
            let (line, col) = ix.line_col(pos.offset);
            self.maps.push(Mapping {
                gen_line: self.line,
                gen_col: (self.depth * 2) as u32,
                source: *source as u32,
                line,
                col,
            });
        }
        for _ in 0..self.depth {
            self.out.push_str("  ");
        }
        self.out.push_str(s);
        self.out.push('\n');
        self.line += 1;
    }

    fn at(&mut self, pos: Option<Pos>) {
        if pos.is_some() {
            self.pending = pos;
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Types

fn type_class(w: &mut W, t: TypeId) {
    let cx = w.cx;
    let td = cx.m.ty(t);
    let name = &cx.type_names[t.index()];
    let schemas = cx.m.field_schemas.get(&t);
    let module = js_string(&td.module);
    match &td.kind {
        TypeKind::Variant { ctors } => {
            w.line(&format!("export class {name} extends $rt.Variant {{}}"));
            let cs: Vec<String> = ctors
                .iter()
                .enumerate()
                .map(|(ci, c)| {
                    let tys = schemas.map_or(&c.fields, |s| &s[ci]);
                    let hs: Vec<String> = tys.iter().map(|f| schema(cx.m, f)).collect();
                    format!("[{}, [{}]]", js_string(&c.name), hs.join(", "))
                })
                .collect();
            w.line(&format!(
                "{name}.prototype.$t = $rt.variantType({}, {module}, [{}]);",
                js_string(&td.name),
                cs.join(", ")
            ));
            for (i, c) in ctors.iter().enumerate() {
                if c.fields.is_empty() {
                    w.line(&format!(
                        "export const {name}${} = Object.freeze(new {name}({i}, []));",
                        ident(&c.name)
                    ));
                }
            }
        }
        TypeKind::Record { fields, error } => {
            let params: Vec<String> = (0..fields.len()).map(|i| format!("${i}")).collect();
            w.line(&format!("export class {name} {{"));
            w.depth += 1;
            w.line(&format!("constructor({}) {{", params.join(", ")));
            w.depth += 1;
            for (i, f) in fields.iter().enumerate() {
                w.line(&format!("this.{} = ${i};", prop(&f.name)));
            }
            w.depth -= 1;
            w.line("}");
            w.depth -= 1;
            w.line("}");
            let fs: Vec<String> = fields
                .iter()
                .enumerate()
                .map(|(fi, f)| {
                    format!(
                        "[{}, {}, {}]",
                        js_string(&f.name),
                        js_string(&prop(&f.name)),
                        schema(cx.m, schemas.map_or(&f.ty, |s| &s[0][fi]))
                    )
                })
                .collect();
            w.line(&format!(
                "{name}.prototype.$t = $rt.recordType({}, {module}, [{}], {error});",
                js_string(&td.name),
                fs.join(", ")
            ));
        }
    }
    w.line(&format!(
        "$rt.def({}, {name});",
        js_string(&td.qualified_name())
    ));
    w.line("");
}

/// The JS property for a record field.
fn prop(field: &str) -> String {
    if field == "__proto__" {
        format!("{field}$")
    } else {
        field.to_owned()
    }
}

/// A type's runtime schema (ABI.md §7) as a JS literal: `"U" "B" "I" "F" "S" "Y"`,
/// `["T", s…]`, `["L", s]`, `["E", s]` (set), `["M", sk, sv]`, `["A", id, [s…]]` (a named type
/// by qualified name), `["W", [id…]]` (error union), `["V", i]` (a type parameter of the
/// enclosing type), `["X", name]` (opaque), `null` (functions, unknown).
pub(crate) fn schema(m: &Module, ty: &Ty) -> String {
    schema_with(m, ty, &[], false)
}

/// [`schema`] with type parameter `vars[i].0` replaced by the JS expression `vars[i].1`; in
/// `code`, other type parameters are unknown (`null`).
fn schema_with(m: &Module, ty: &Ty, vars: &[(u32, String)], code: bool) -> String {
    let schema = |m: &Module, t: &Ty| schema_with(m, t, vars, code);
    let all = |ts: &[Ty]| {
        ts.iter()
            .map(|t| schema(m, t))
            .collect::<Vec<_>>()
            .join(", ")
    };
    match ty {
        Ty::Unit => "\"U\"".into(),
        Ty::Bool => "\"B\"".into(),
        Ty::Int => "\"I\"".into(),
        Ty::Float => "\"F\"".into(),
        Ty::String => "\"S\"".into(),
        Ty::Bytes => "\"Y\"".into(),
        Ty::Tuple(ts) => format!("[\"T\", {}]", all(ts)),
        Ty::List(t) => format!("[\"L\", {}]", schema(m, t)),
        Ty::Set(t) => format!("[\"E\", {}]", schema(m, t)),
        Ty::Map(k, v) => format!("[\"M\", {}, {}]", schema(m, k), schema(m, v)),
        Ty::Adt(t, args) => format!(
            "[\"A\", {}, [{}]]",
            js_string(&m.ty(*t).qualified_name()),
            all(args)
        ),
        Ty::Union(ts) => {
            let ids: Vec<String> = ts
                .iter()
                .map(|t| js_string(&m.ty(*t).qualified_name()))
                .collect();
            format!("[\"W\", [{}]]", ids.join(", "))
        }
        Ty::Refined(r, args) => format!(
            "[\"A\", {}, [{}]]",
            js_string(&m.refinements[r.index()].qualified_name()),
            all(args)
        ),
        Ty::Var(i) if let Some((_, js)) = vars.iter().find(|(v, _)| v == i) => js.clone(),
        // In code, an unsolved type parameter has no runtime schema; in type descriptors
        // `["V", i]` is the descriptor's own parameter.
        Ty::Var(_) if code => "null".into(),
        Ty::Var(i) if *i != u32::MAX => format!("[\"V\", {i}]"),
        Ty::Opaque(name) => format!("[\"X\", {}]", js_string(name)),
        Ty::Never | Ty::Fn(_) | Ty::Handler(_) | Ty::Instance(_) | Ty::Var(_) => "null".into(),
    }
}

// ---------------------------------------------------------------------------------------------
// Functions

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Cps,
    Direct,
}

#[derive(Default)]
struct LabelInfo {
    /// Emitted as a labelled block or loop in the defining JS function.
    inline: bool,
    /// Jumped to from its own join body (a loop).
    recursive: bool,
    params: Vec<Local>,
}

struct FnEmit<'a> {
    cx: &'a Cx<'a>,
    id: DefId,
    def: &'a FnDef,
    module: &'a str,
    mode: Mode,
    names: Vec<String>,
    labels: HashMap<Label, LabelInfo>,
    /// Inline recursive labels whose loop body is being emitted.
    in_loop: Vec<Label>,
    /// Inline recursive labels whose entry block is being emitted.
    in_entry: Vec<Label>,
    ctxs: u32,
    /// Locals bound to a closure of a known def: a call of one with a twin is inlined.
    closures: Closures,
    /// Handler literals and the performs bound to them (design §17.113).
    bound: Bound,
    /// The `Handle`s over a handler literal being emitted, innermost last: the handler's local
    /// and the JS name of the instance.
    insts: Vec<(Local, String)>,
    /// Direct code: how often each local is read, and the producer expressions of one-use
    /// temporaries inlined into their consumer (see [`FnEmit::fuses`]).
    uses: HashMap<Local, u32>,
    inlined: HashMap<Local, String>,
    ns: &'a RefCell<BTreeSet<String>>,
    pool: &'a Pool,
    /// Locals bound by an `Int` operation the interval pass proves (design §17.114).
    proved: Vec<bool>,
    /// Consuming sites whose argument is owned: they call the in-place entry (design §17.149).
    owned: owned::Facts,
    /// `$d`, or `$o` for the owned entry of a consuming def.
    twin: &'static str,
    /// The `contract_enter`/`contract_exit` binds around predicates that cannot defect.
    unbracketed: HashSet<Local>,
}

impl<'a> FnEmit<'a> {
    fn new(
        cx: &'a Cx<'a>,
        id: DefId,
        module: &'a str,
        module_defs: &[&str],
        mode: Mode,
        ns: &'a RefCell<BTreeSet<String>>,
        pool: &'a Pool,
    ) -> Self {
        let def = cx.m.def(id);
        let mut taken: HashSet<String> = module_defs.iter().map(|s| (*s).to_owned()).collect();
        taken.extend(module_defs.iter().map(|s| format!("{s}$d")));
        // The next suffix to try per base name, so 100,000 locals called `t` stay linear.
        let mut next: HashMap<String, u32> = HashMap::new();
        let names = def
            .locals
            .iter()
            .map(|l| {
                let base = ident(&l.name);
                let n = next.entry(base.clone()).or_insert(0);
                let mut name = if *n == 0 {
                    base.clone()
                } else {
                    format!("{base}_{n}")
                };
                while taken.contains(&name) || RESERVED.contains(&name.as_str()) {
                    *n += 1;
                    name = format!("{base}_{n}");
                }
                *n += 1;
                taken.insert(name.clone());
                name
            })
            .collect();
        let mut e = FnEmit {
            cx,
            id,
            def,
            module,
            mode,
            names,
            labels: HashMap::new(),
            in_loop: Vec::new(),
            in_entry: Vec::new(),
            ctxs: 0,
            closures: direct::closures(def),
            bound: handlers::bind(cx.m, def),
            insts: Vec::new(),
            uses: HashMap::new(),
            inlined: HashMap::new(),
            ns,
            pool,
            proved: sakura_core::opt::ranges::analyze(
                cx.m,
                def,
                sakura_core::opt::ranges::Profile::Js,
            ),
            owned: owned::analyze(cx.m, def, &cx.summaries, &[]),
            twin: "$d",
            unbracketed: HashSet::new(),
        };
        e.analyze_labels();
        brackets(&def.body, &e.proved, &mut e.unbracketed);
        if mode == Mode::Direct {
            count_uses(&def.body, &mut e.uses);
        }
        e
    }

    /// Make this the owned entry `f$o`: the twin with the consumed parameter owned.
    fn owned_entry(&mut self) {
        let p = self.cx.summaries[self.id.index()]
            .consumes
            .map(|p| self.def.params[p]);
        self.owned = owned::analyze(self.cx.m, self.def, &self.cx.summaries, &Vec::from_iter(p));
        self.twin = "$o";
    }

    fn name(&self, l: Local) -> &str {
        &self.names[l.index()]
    }

    fn def(mut self, w: &mut W) {
        let d = self.def;
        let name = self.cx.def_names[self.id.index()].clone();
        // Lambdas and clauses too: an inlined handler constructor (design §17.113) builds its
        // clause closures in the caller's module.
        let export = "export ";
        let constant = d.kind == FnKind::Const;
        // A constant's body is `name$init`; `name` evaluates it once and caches the value.
        let body_name = if constant {
            format!("{name}$init")
        } else {
            name.clone()
        };
        let body_export = if constant { "" } else { export };
        let mut params: Vec<String> = d
            .captures
            .iter()
            .chain(&d.params)
            .map(|l| self.name(*l).to_owned())
            .collect();
        // A def that blames its caller is told the call site (design §17.115): trailing in both
        // ABIs, so a call through a function value, which passes none, leaves it `undefined`.
        let takes_site = self.cx.takes_site[self.id.index()];
        let site = if takes_site { ", $site" } else { "" };
        w.at(d.pos);
        match self.mode {
            Mode::Direct => {
                w.line(&format!(
                    "{body_export}function {body_name}{}({}{site}) {{",
                    self.twin,
                    params.join(", ")
                ));
                w.depth += 1;
                if self.cx.direct.recursive(self.id) {
                    // The first `LIMIT` frames run here; the rest on the heap (design §17.112).
                    w.line(&format!(
                        "if ($G.d >= $L) return $rt.runSync({body_name}, [{}]{site});",
                        params.join(", ")
                    ));
                    w.line("++$G.d;");
                }
                self.expr(w, &d.body, "");
                w.depth -= 1;
                w.line("}");
                if constant {
                    w.line(&format!("{export}function {name}$d() {{"));
                    w.depth += 1;
                    w.line(&format!(
                        "if (!{name}$once) {{ {name}$value = {name}$init$d(); {name}$once = true; }}"
                    ));
                    w.line(&format!("return {name}$value;"));
                    w.depth -= 1;
                    w.line("}");
                }
            }
            Mode::Cps if self.cx.direct.direct(self.id) && !self.cx.direct.recursive(self.id) => {
                if constant {
                    w.line(&format!("let {name}$once = false, {name}$value;"));
                }
                let ps = params.join(", ");
                params.extend(["$ctx".into(), "$k".into()]);
                if takes_site {
                    params.push("$site".into());
                }
                w.line(&format!(
                    "{export}function {name}({}) {{",
                    params.join(", ")
                ));
                w.depth += 1;
                // The twin assumes its function-typed arguments carry `$d` (design §17.111);
                // otherwise the CPS body runs.
                let tests: Vec<String> = d
                    .params
                    .iter()
                    .filter(|p| direct::fn_param(d, **p))
                    .map(|p| format!("{}.$d !== undefined", self.name(*p)))
                    .collect();
                let twin = format!("return $ret($k, {name}$d({ps}{site}));");
                if tests.is_empty() {
                    w.line(&twin);
                } else {
                    w.line(&format!("if ({}) {twin}", tests.join(" && ")));
                    w.line(&format!(
                        "if (++$G.d > $L) return $b({name}, [{}]);",
                        params.join(", ")
                    ));
                    self.expr(w, &d.body, "$ctx");
                }
                w.depth -= 1;
                w.line("}");
                if self.cx.direct.exposes(self.id) && d.captures.is_empty() {
                    w.line(&format!("{name}.$d = {name}$d;"));
                }
            }
            Mode::Cps => {
                params.extend(["$ctx".into(), "$k".into()]);
                if takes_site {
                    params.push("$site".into());
                }
                let ps = params.join(", ");
                w.line(&format!("{body_export}function {body_name}({ps}) {{"));
                w.depth += 1;
                w.line(&format!("if (++$G.d > $L) return $b({body_name}, [{ps}]);"));
                self.expr(w, &d.body, "$ctx");
                w.depth -= 1;
                w.line("}");
                // A recursive direct def keeps its CPS body as the entry, so `runSync` and
                // values called from CPS code never re-enter the twin (design §17.112).
                if self.cx.direct.exposes(self.id) && d.captures.is_empty() {
                    w.line(&format!("{name}.$d = {name}$d;"));
                }
                if constant {
                    w.line(&format!("let {name}$once = false, {name}$value;"));
                    w.line(&format!("{export}function {name}($ctx, $k) {{"));
                    w.depth += 1;
                    w.line(&format!("if ({name}$once) return $ret($k, {name}$value);"));
                    w.line(&format!(
                        "return {name}$init($ctx, (v) => {{ {name}$value = v; {name}$once = true; return $ret($k, v); }});"
                    ));
                    w.depth -= 1;
                    w.line("}");
                }
            }
        }
        w.line("");
    }

    /// The trailing site argument (`, 7`) of a call to a def that blames its caller, so its
    /// contract defects name this call (design §7.2, §17.115); `-1` when the call has no span.
    fn site_arg(&self, callee: &Atom, pos: Option<Pos>) -> String {
        match callee {
            Atom::Global(d) if self.cx.takes_site[d.index()] => format!(", {}", self.site(pos)),
            _ => String::new(),
        }
    }

    fn site(&self, pos: Option<Pos>) -> i64 {
        match self.span(pos) {
            s if s == "null" => -1,
            s => self.pool.site(s).into(),
        }
    }

    /// A source span as a pooled `{ uri, start_byte, end_byte }`, or `null`.
    fn span(&self, pos: Option<Pos>) -> String {
        match pos.and_then(|p| Some((p, self.cx.lines.get(&p.file)?.0))) {
            Some((p, source)) => self.pool.get(format!(
                "{{ uri: {}, start_byte: {}, end_byte: {} }}",
                js_string(&self.cx.sources[source]),
                p.offset,
                p.end
            )),
            None => "null".into(),
        }
    }

    // -----------------------------------------------------------------------------------------
    // Join point analysis

    fn analyze_labels(&mut self) {
        let mut infos = HashMap::new();
        collect_labels(&self.def.body, &mut infos, &mut Vec::new());
        self.labels = infos;
        loop {
            let mut frames = Frames::default();
            self.frames(&self.def.body, 0, &mut frames);
            let mut changed = false;
            for (label, info) in self.labels.iter_mut() {
                let def_frame = frames.def.get(label).copied();
                let bad = frames.no_inline.contains(label)
                    || frames
                        .jumps
                        .get(label)
                        .is_some_and(|js| js.iter().any(|f| Some(*f) != def_frame));
                if info.inline && bad {
                    info.inline = false;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
        assert!(
            self.mode == Mode::Cps || self.labels.values().all(|l| l.inline),
            "direct-style bodies only use inline join points ({})",
            self.def.name
        );
    }

    fn frames(&self, e: &Expr, frame: u32, f: &mut Frames) {
        sakura_core::ensure_stack(|| self.frames_inner(e, frame, f))
    }

    fn frames_inner(&self, e: &Expr, frame: u32, f: &mut Frames) {
        match e {
            Expr::Let {
                local, bind, body, ..
            } => {
                let inner = if self.is_cps(*local, bind) {
                    f.fresh()
                } else {
                    frame
                };
                self.frames(body, inner, f);
            }
            Expr::Ret(_) | Expr::Fail(_) => {}
            Expr::Jump(l, _) => f.jumps.entry(*l).or_default().push(frame),
            Expr::LetJoin {
                label, join, body, ..
            } => {
                f.def.insert(*label, frame);
                let jf = if self.labels[label].inline {
                    frame
                } else {
                    f.fresh()
                };
                self.frames(join, jf, f);
                self.frames(body, frame, f);
            }
            Expr::Switch { arms, default, .. } => {
                for (_, a) in arms {
                    self.frames(a, frame, f);
                }
                if let Some(d) = default {
                    self.frames(d, frame, f);
                }
            }
            Expr::If { then, els, .. } => {
                self.frames(then, frame, f);
                self.frames(els, frame, f);
            }
            Expr::Handle { body, .. } => self.frames(body, frame, f),
            Expr::Try { on_fail, body } => {
                f.no_inline.insert(*on_fail);
                self.frames(body, frame, f);
            }
        }
    }

    /// Does this binding (of `x`) transfer control through a continuation?
    fn is_cps(&self, x: Local, b: &Bind) -> bool {
        match b {
            Bind::Perform(..) => self.bound_clause(x, b).is_none(),
            // The CPS body of a recursive def may run under `runSync`: it calls every recursive
            // def through its CPS body, so no nested driver starts (design §17.112).
            Bind::Call(callee, _)
                if self.mode == Mode::Cps
                    && self.cx.direct.recursive(self.id)
                    && self
                        .callee_def(callee)
                        .is_some_and(|d| self.cx.direct.recursive(d)) =>
            {
                true
            }
            Bind::Call(callee, args) => !self.cx.direct.call_ok(
                self.cx.m,
                self.def,
                &self.closures,
                self.mode == Mode::Direct,
                callee,
                args,
            ),
            _ => false,
        }
    }

    /// The direct clause a perform bound to a handler literal calls (design §17.113): its def,
    /// the closure's captures and the handler's local.
    fn bound_clause(&self, x: Local, b: &Bind) -> Option<(DefId, &[Atom], Local)> {
        match b {
            Bind::Perform(_, op, _) => direct::bound_clause(&self.bound, &self.closures, x, *op)
                .filter(|(d, _, _)| self.cx.direct.direct(*d)),
            _ => None,
        }
    }

    /// The def a call reaches statically: a global or a closure-bound local.
    fn callee_def(&self, callee: &Atom) -> Option<DefId> {
        match callee {
            Atom::Global(d) => Some(*d),
            Atom::Local(l) => self.closures.get(l).map(|(d, _)| *d),
            _ => None,
        }
    }

    // -----------------------------------------------------------------------------------------
    // Expressions

    fn ret(&self, value: &str) -> String {
        match self.mode {
            Mode::Cps => format!("return $ret($k, {value});"),
            Mode::Direct if self.cx.direct.recursive(self.id) => {
                format!("--$G.d; return {value};")
            }
            Mode::Direct => format!("return {value};"),
        }
    }

    fn fresh_ctx(&mut self) -> String {
        self.ctxs += 1;
        format!("$ctx{}", self.ctxs)
    }

    fn expr(&mut self, w: &mut W, e: &Expr, ctx: &str) {
        sakura_core::ensure_stack(|| self.expr_inner(w, e, ctx))
    }

    fn expr_inner(&mut self, w: &mut W, e: &Expr, ctx: &str) {
        match e {
            Expr::Let {
                local,
                bind,
                pos,
                body,
            } => {
                w.at(*pos);
                if self.is_cps(*local, bind) {
                    self.cps_call(w, *local, bind, *pos, body, ctx);
                } else {
                    self.simple_bind(w, *local, bind, *pos, body);
                    self.expr(w, body, ctx);
                }
            }
            Expr::Ret(a) => {
                let s = self.ret(&self.atom(a));
                w.line(&s);
            }
            Expr::Fail(a) => {
                let s = format!("return $rt.fail({ctx}, {});", self.atom(a));
                w.line(&s);
            }
            Expr::Jump(l, args) => self.jump(w, *l, args),
            Expr::LetJoin {
                label,
                params,
                join,
                body,
            } => self.let_join(w, *label, params, join, body, ctx),
            Expr::Switch {
                scrut,
                on,
                arms,
                default,
            } => {
                let s = self.atom(scrut);
                match on {
                    SwitchOn::Variant(_) => {
                        w.line(&format!("switch ({s}.tag) {{"));
                        w.depth += 1;
                        for (key, arm) in arms {
                            w.line(&format!("case {key}: {{"));
                            w.depth += 1;
                            self.expr(w, arm, ctx);
                            w.depth -= 1;
                            w.line("}");
                        }
                        if let Some(d) = default {
                            w.line("default: {");
                            w.depth += 1;
                            self.expr(w, d, ctx);
                            w.depth -= 1;
                            w.line("}");
                        }
                        w.depth -= 1;
                        w.line("}");
                    }
                    SwitchOn::Errors(ts) => {
                        for (i, (key, arm)) in arms.iter().enumerate() {
                            let class = self.type_ref(ts[*key as usize]);
                            let kw = if i == 0 { "if" } else { "} else if" };
                            w.line(&format!("{kw} ({s} instanceof {class}) {{"));
                            w.depth += 1;
                            self.expr(w, arm, ctx);
                            w.depth -= 1;
                        }
                        match default {
                            Some(d) if arms.is_empty() => self.expr(w, d, ctx),
                            Some(d) => {
                                w.line("} else {");
                                w.depth += 1;
                                self.expr(w, d, ctx);
                                w.depth -= 1;
                                w.line("}");
                            }
                            None if arms.is_empty() => {}
                            None => w.line("}"),
                        }
                    }
                }
            }
            Expr::If { cond, then, els } => {
                w.line(&format!("if ({}) {{", self.atom(cond)));
                w.depth += 1;
                self.expr(w, then, ctx);
                w.depth -= 1;
                w.line("} else {");
                w.depth += 1;
                self.expr(w, els, ctx);
                w.depth -= 1;
                w.line("}");
            }
            Expr::Handle { handler, body } => {
                let h = self.atom(handler);
                let lit = match handler {
                    Atom::Local(l) if self.bound.performs.values().any(|h| h == l) => Some(*l),
                    _ => None,
                };
                let c = self.fresh_ctx();
                // Direct code has no context: only bound performs reach the instance.
                let c = if self.mode == Mode::Direct {
                    ctx.to_owned()
                } else {
                    w.line(&format!("const {c} = $rt.install({ctx}, {h});"));
                    c
                };
                if let Some(l) = lit {
                    let i = format!("$i{}", self.ctxs);
                    w.line(&if self.mode == Mode::Direct {
                        format!("const {i} = $rt.instance({h});")
                    } else {
                        format!("const {i} = {c}.h.i;")
                    });
                    self.insts.push((l, i));
                }
                self.expr(w, body, &c);
                if lit.is_some() {
                    self.insts.pop();
                }
            }
            Expr::Try { on_fail, body } => {
                let c = self.fresh_ctx();
                w.line(&format!("const {c} = $rt.catcher({ctx}, j{});", on_fail.0));
                self.expr(w, body, &c);
            }
        }
    }

    fn cps_call(
        &mut self,
        w: &mut W,
        x: Local,
        bind: &Bind,
        pos: Option<Pos>,
        body: &Expr,
        ctx: &str,
    ) {
        // The continuation: `$k` for a tail call, a join point for `jump j(x)`, else an arrow.
        let xs = self.name(x).to_owned();
        let k = match body {
            Expr::Ret(Atom::Local(r)) if *r == x && self.mode == Mode::Cps => Some("$k".to_owned()),
            Expr::Jump(l, args)
                if args.as_slice() == [Atom::Local(x)] && !self.labels[l].inline =>
            {
                Some(format!("j{}", l.0))
            }
            _ => None,
        };
        // `callee(args…, ctx, ` — the continuation, `site` and closing parenthesis follow.
        let mut site = String::new();
        let head = match bind {
            Bind::Perform(e, op, args)
                if self.cx.direct.enabled
                    && !self.cx.m.effect(*e).ops[*op as usize]
                        .params
                        .iter()
                        .any(direct::is_fn) =>
            {
                // Tail-direct dispatch (design §17.113): a clause with a twin runs inline; the
                // continuation is shared by both paths.
                let (f, c) = (format!("$f{}", x.0), format!("$cl{}", x.0));
                let eff = js_string(&self.cx.m.effect(*e).qualified_name());
                w.line(&format!(
                    "const {f} = $rt.find({ctx}, {eff}, {op}), {c} = {f}.i.c[{op}];"
                ));
                let k = match k {
                    Some(k) => k,
                    None => {
                        let k = format!("$k{}", x.0);
                        w.line(&format!("const {k} = ({xs}) => {{"));
                        w.depth += 1;
                        self.expr(w, body, ctx);
                        w.depth -= 1;
                        w.line("};");
                        k
                    }
                };
                let a: Vec<String> = std::iter::once(format!("{f}.i"))
                    .chain(args.iter().map(|a| self.atom(a)))
                    .collect();
                let a = a.join(", ");
                w.line(&format!(
                    "if ({c}.$d !== undefined) return $ret({k}, {c}.$d({a}));"
                ));
                w.line(&format!("return {c}({a}, $rt.cctx({ctx}, {f}), {k});"));
                return;
            }
            Bind::Perform(e, op, args) => {
                let f = format!("$f{}", x.0);
                let eff = js_string(&self.cx.m.effect(*e).qualified_name());
                w.line(&format!("const {f} = $rt.find({ctx}, {eff}, {op});"));
                let mut a = vec![format!("{f}.i")];
                // Function-typed arguments are callbacks: they run under the perform site's
                // handlers wherever the clause calls them (design §5.5, ABI.md §3).
                let params = &self.cx.m.effect(*e).ops[*op as usize].params;
                a.extend(args.iter().enumerate().map(|(i, x)| match params.get(i) {
                    Some(Ty::Fn(_)) => format!("$rt.callback({}, {ctx})", self.atom(x)),
                    _ => self.atom(x),
                }));
                a.push(format!("$rt.cctx({ctx}, {f})"));
                format!("{f}.i.c[{op}]({}, ", a.join(", "))
            }
            Bind::Call(callee, args) => {
                site = self.site_arg(callee, pos);
                let mut a: Vec<String> = args.iter().map(|x| self.atom(x)).collect();
                a.push(ctx.to_owned());
                let f = match callee {
                    Atom::Builtin(name) => format!("$rt.{name}"),
                    other => self.atom(other),
                };
                format!("{f}({}, ", a.join(", "))
            }
            _ => unreachable!("not a CPS binding"),
        };
        match k {
            Some(k) => w.line(&format!("return {head}{k}{site});")),
            None => {
                w.line(&format!("return {head}({xs}) => {{"));
                w.depth += 1;
                self.expr(w, body, ctx);
                w.depth -= 1;
                w.line(&format!("}}{site});"));
            }
        }
    }

    /// In direct code, a reference-valued temporary read once, by the next binding, is
    /// inlined into it: `check$d(bottom_up$d(t))`, not `const r = bottom_up$d(t);
    /// check$d(r);`, which keeps `r` (a whole tree) reachable from the frame until the
    /// function returns. The consumer is a call that emits no statement before its
    /// expression (no check or bound perform), and its other operands are
    /// plain reads, so the producer still runs right after the statements before it and
    /// before the consumer. Not an allocation: V8 allocates `new T(1, [a, f()])`'s array
    /// before calling `f`, and that array then survives everything `f` allocates.
    fn fuses(&self, x: Local, bind: &Bind, body: &Expr) -> bool {
        let reference = !matches!(
            self.def.local(x).ty,
            Ty::Unit | Ty::Bool | Ty::Int | Ty::Float
        );
        let consumer = match body {
            Expr::Let {
                bind: Bind::Call(callee, args),
                ..
            } => *callee != Atom::Local(x) && args.contains(&Atom::Local(x)),
            _ => false,
        };
        self.mode == Mode::Direct
            && reference
            && consumer
            && matches!(bind, Bind::Call(..) | Bind::Alloc(..))
            && self.uses.get(&x) == Some(&1)
    }

    fn simple_bind(&mut self, w: &mut W, x: Local, bind: &Bind, pos: Option<Pos>, body: &Expr) {
        let xs = self.name(x).to_owned();
        let rhs = match bind {
            // A self tail call's position: the next iteration's checks blame it (design §17.115).
            Bind::Atom(_)
                if self.cx.takes_site[self.id.index()]
                    && self.def.local(x).name == sakura_core::opt::SITE_MARK =>
            {
                w.line(&format!("$site = {};", self.site(pos)));
                return;
            }
            // The `D011` bracket around a predicate that cannot defect (design §17.115).
            Bind::Call(Atom::Builtin(_), _) if self.unbracketed.contains(&x) => return,
            Bind::Atom(a) => self.atom(a),
            // The inline fast path (design §17.114): an unsafe result means the checked
            // operation defects, so `$rt.add`/`sub`/`mul` run only to raise it.
            Bind::Prim(op @ (PrimOp::IntAdd | PrimOp::IntSub | PrimOp::IntMul), args)
                if !self.proved[x.index()] =>
            {
                let raw = self.prim(op, args, true);
                let slow = self.prim(op, args, false);
                w.line(&format!("const {xs} = {raw};"));
                w.line(&format!("if (!Number.isSafeInteger({xs})) {slow};"));
                return;
            }
            Bind::Prim(op, args) => self.prim(op, args, self.proved[x.index()]),
            Bind::Call(f @ Atom::Global(d), args) => {
                // An owned argument goes to the callee's owned entry (design §17.149).
                let twin = if self.owned.owned(x) { "$o" } else { "$d" };
                format!(
                    "{}{twin}({}{})",
                    self.def_ref(*d),
                    self.atoms(args),
                    self.site_arg(f, pos)
                )
            }
            Bind::Call(Atom::Builtin(name), args) => {
                let owned = if self.owned.owned(x) { "_owned" } else { "" };
                format!("$rt.{name}{owned}({})", self.atoms(args))
            }
            // A closure of a direct def bound in this function, or (in a twin) a function-typed
            // parameter, which carries `$d`.
            Bind::Call(Atom::Local(l), args) => match self.closures.get(l) {
                Some((d, caps)) => format!(
                    "{}$d({})",
                    self.def_ref(*d),
                    self.atoms(&[caps.as_slice(), args].concat())
                ),
                None => format!("{}.$d({})", self.name(*l), self.atoms(args)),
            },
            Bind::Perform(e, op, args) => {
                let (clause, caps, h) = self.bound_clause(x, bind).expect("CPS binding");
                let inst = &self
                    .insts
                    .iter()
                    .rev()
                    .find(|(l, _)| *l == h)
                    .expect("bound perform outside its handler")
                    .1;
                // Still a cancellation point, and traced (design §17.113).
                w.line(&format!(
                    "if ($T.t.cancelled || $tr) $rt.bound({}, {op});",
                    js_string(&self.cx.m.effect(*e).qualified_name())
                ));
                let a: Vec<String> = caps
                    .iter()
                    .map(|c| self.atom(c))
                    .chain([inst.clone()])
                    .chain(args.iter().map(|a| self.atom(a)))
                    .collect();
                format!("{}$d({})", self.def_ref(clause), a.join(", "))
            }
            Bind::Call(..) => unreachable!("CPS binding"),
            Bind::Closure(d, caps) => {
                let f = self.def_ref(*d);
                if caps.is_empty() {
                    f
                } else {
                    let caps = self.atoms(caps);
                    if self.cx.direct.exposes(*d) {
                        w.line(&format!("const {xs} = {f}.bind(null, {caps});"));
                        w.line(&format!("{xs}.$d = {f}$d.bind(null, {caps});"));
                        return;
                    }
                    format!("{f}.bind(null, {caps})")
                }
            }
            Bind::Alloc(alloc, args) => self.alloc(alloc, args),
            Bind::Proj(a, p) => {
                let a = self.atom(a);
                match p {
                    Proj::Tuple(i) => format!("{a}[{i}]"),
                    Proj::Field(t, i) => {
                        format!("{a}.{}", prop(&self.cx.m.ty(*t).fields()[*i as usize].name))
                    }
                    Proj::Payload(_, _, i) => format!("{a}.fields[{i}]"),
                }
            }
            Bind::Check(c, cond) => {
                let decl = &self.cx.m.contracts[c.index()];
                let what = match decl.kind {
                    ContractKind::Requires => "precondition",
                    ContractKind::Ensures => "postcondition",
                    ContractKind::Where => "refinement",
                };
                // A refinement is named by its type (`Percent`, `Ticket.title`); a clause by its
                // function.
                let msg = js_string(&match decl.kind {
                    ContractKind::Where => format!("{what} `{}` violated", decl.name),
                    _ => format!("{what} `{}` of {} violated", decl.name, self.def.name),
                });
                let site = if decl.kind == ContractKind::Ensures {
                    "-1"
                } else {
                    "$site"
                };
                w.line(&format!(
                    "if (!{}) $rt.violated({}, {msg}, {site}, {});",
                    self.atom(cond),
                    js_string(decl.defect_code()),
                    self.span(decl.pos)
                ));
                "undefined".into()
            }
            Bind::MakeHandler {
                effect,
                state,
                clauses,
            } => format!(
                "$rt.makeHandler({}, [{}], [{}])",
                js_string(&self.cx.m.effect(*effect).qualified_name()),
                self.atoms(state),
                self.atoms(clauses)
            ),
            Bind::StateGet(inst, i) => format!("{}.s{i}", self.atom(inst)),
            Bind::StateSet(inst, i, v) => {
                w.line(&format!("{}.s{i} = {};", self.atom(inst), self.atom(v)));
                "undefined".into()
            }
            Bind::Hole(h) => format!("$rt.defect(\"D090\", \"typed hole ?{h} was evaluated\")"),
        };
        if self.fuses(x, bind, body) {
            self.inlined.insert(x, rhs);
        } else {
            w.line(&format!("const {xs} = {rhs};"));
        }
    }

    fn jump(&mut self, w: &mut W, l: Label, args: &[Atom]) {
        let info = &self.labels[&l];
        if !info.inline {
            let s = format!("return j{}({});", l.0, self.atoms(args));
            w.line(&s);
            return;
        }
        let params = info.params.clone();
        self.assign(w, &params, args);
        if self.in_loop.contains(&l) {
            w.line(&format!("continue j{};", l.0));
        } else if self.in_entry.contains(&l) {
            w.line(&format!("break j{}$e;", l.0));
        } else {
            w.line(&format!("break j{};", l.0));
        }
    }

    /// Parallel assignment of jump arguments to an inline join's parameters.
    fn assign(&self, w: &mut W, params: &[Local], args: &[Atom]) {
        let clash = args.iter().enumerate().any(|(i, a)| {
            matches!(a, Atom::Local(l) if params.iter().position(|p| p == l).is_some_and(|j| j != i))
        });
        if clash {
            let tmps: Vec<String> = args
                .iter()
                .enumerate()
                .map(|(i, a)| format!("$t{i} = {}", self.atom(a)))
                .collect();
            w.line(&format!("const {};", tmps.join(", ")));
            for (i, p) in params.iter().enumerate() {
                w.line(&format!("{} = $t{i};", self.name(*p)));
            }
        } else {
            for (p, a) in params.iter().zip(args) {
                if *a != Atom::Local(*p) {
                    w.line(&format!("{} = {};", self.name(*p), self.atom(a)));
                }
            }
        }
    }

    fn let_join(
        &mut self,
        w: &mut W,
        label: Label,
        params: &[Local],
        join: &Expr,
        body: &Expr,
        ctx: &str,
    ) {
        let info = &self.labels[&label];
        let (inline, recursive) = (info.inline, info.recursive);
        let ps: Vec<String> = params.iter().map(|p| self.name(*p).to_owned()).collect();
        let ps = ps.join(", ");
        let j = format!("j{}", label.0);
        if !inline {
            w.line(&format!("const {j} = ({ps}) => {{"));
            w.depth += 1;
            if recursive {
                w.line(&format!("if (++$G.d > $L) return $b({j}, [{ps}]);"));
            }
            self.expr(w, join, ctx);
            w.depth -= 1;
            w.line("};");
            self.expr(w, body, ctx);
            return;
        }
        if !params.is_empty() {
            w.line(&format!("let {ps};"));
        }
        // Entry: run `body`; its jumps to `label` fall through to the join code below.
        let entry_label = if recursive {
            format!("{j}$e")
        } else {
            j.clone()
        };
        match body {
            Expr::Jump(l, args) if *l == label => self.assign(w, params, args),
            _ => {
                w.line(&format!("{entry_label}: {{"));
                w.depth += 1;
                if recursive {
                    self.in_entry.push(label);
                }
                self.expr(w, body, ctx);
                if recursive {
                    self.in_entry.pop();
                }
                w.depth -= 1;
                w.line("}");
            }
        }
        if recursive {
            w.line(&format!("{j}: for (;;) {{"));
            w.depth += 1;
            self.in_loop.push(label);
            self.expr(w, join, ctx);
            self.in_loop.pop();
            w.depth -= 1;
            w.line("}");
        } else {
            self.expr(w, join, ctx);
        }
    }

    // -----------------------------------------------------------------------------------------
    // Atoms and operators

    fn atoms(&self, atoms: &[Atom]) -> String {
        atoms
            .iter()
            .map(|a| self.atom(a))
            .collect::<Vec<_>>()
            .join(", ")
    }

    fn atom(&self, a: &Atom) -> String {
        match a {
            Atom::Local(l) => match self.inlined.get(l) {
                Some(e) => e.clone(),
                None => self.name(*l).to_owned(),
            },
            Atom::Lit(lit) => lit_js(lit),
            Atom::Global(d) => self.def_ref(*d),
            Atom::Builtin(name) => match builtins::lookup(name) {
                Some(b) if b.abi == Abi::Direct => {
                    let ps: Vec<String> = (0..b.arity).map(|i| format!("$a{i}")).collect();
                    let ps = ps.join(", ");
                    let sep = if ps.is_empty() { "" } else { ", " };
                    format!("(({ps}{sep}$ctx, $k) => $ret($k, $rt.{name}({ps})))")
                }
                _ => format!("$rt.{name}"),
            },
        }
    }

    fn def_ref(&self, d: DefId) -> String {
        let name = &self.cx.def_names[d.index()];
        let module = &self.cx.m.def(d).module;
        if module == self.module {
            name.clone()
        } else {
            format!("{}.{name}", self.import(module))
        }
    }

    fn type_ref(&self, t: TypeId) -> String {
        let name = &self.cx.type_names[t.index()];
        let module = &self.cx.m.ty(t).module;
        if module == self.module {
            name.clone()
        } else {
            format!("{}.{name}", self.import(module))
        }
    }

    fn import(&self, module: &str) -> String {
        self.ns.borrow_mut().insert(module.to_owned());
        ns_name(module)
    }

    fn alloc(&mut self, alloc: &Alloc, args: &[Atom]) -> String {
        let a = self.atoms(args);
        match alloc {
            Alloc::Tuple => format!("[{a}]"),
            Alloc::List => format!("$rt.list([{a}])"),
            Alloc::Record(t) => format!("new {}({a})", self.type_ref(*t)),
            Alloc::Variant(t, c) => {
                let td = self.cx.m.ty(*t);
                match (td.builtin.as_deref(), c) {
                    (Some("Option"), 0) => "$rt.None".into(),
                    (Some("Option"), _) => format!("$rt.Some({a})"),
                    (Some("Result"), 0) => format!("$rt.Ok({a})"),
                    (Some("Result"), _) => format!("$rt.Err({a})"),
                    _ => {
                        let class = self.type_ref(*t);
                        if args.is_empty() {
                            format!("{class}${}", ident(&td.ctors()[*c as usize].name))
                        } else {
                            format!("new {class}({c}, [{a}])")
                        }
                    }
                }
            }
        }
    }

    /// `proved`: the operation cannot leave ±(2^53−1) or divide by zero, so it needs no check.
    fn prim(&mut self, op: &PrimOp, args: &[Atom], proved: bool) -> String {
        let a: Vec<String> = args.iter().map(|x| self.atom(x)).collect();
        let bin = |o: &str| format!("({} {o} {})", a[0], a[1]);
        let cmp = |t: &CmpTy, o: &str| match t {
            CmpTy::Int | CmpTy::Float => bin(o),
            _ => format!("($rt.cmp({}, {}) {o} 0)", a[0], a[1]),
        };
        let eq = |t: &CmpTy, neg: bool| match t {
            CmpTy::Any => format!("{}$rt.eq({}, {})", if neg { "!" } else { "" }, a[0], a[1]),
            _ => bin(if neg { "!==" } else { "===" }),
        };
        match op {
            // `+ 0` turns a `-0` into `0`, as the runtime's checked versions do.
            PrimOp::IntAdd if proved => bin("+"),
            PrimOp::IntSub if proved => bin("-"),
            PrimOp::IntMul if proved => format!("({} * {} + 0)", a[0], a[1]),
            PrimOp::IntDiv if proved => format!("(({0} - {0} % {1}) / {1} + 0)", a[0], a[1]),
            PrimOp::IntRem if proved => format!("({} % {} + 0)", a[0], a[1]),
            PrimOp::IntAdd => format!("$rt.add({}, {})", a[0], a[1]),
            PrimOp::IntSub => format!("$rt.sub({}, {})", a[0], a[1]),
            PrimOp::IntMul => format!("$rt.mul({}, {})", a[0], a[1]),
            PrimOp::IntDiv => format!("$rt.div({}, {})", a[0], a[1]),
            PrimOp::IntRem => format!("$rt.rem({}, {})", a[0], a[1]),
            PrimOp::IntNeg => format!("$rt.neg({})", a[0]),
            PrimOp::FloatAdd | PrimOp::Concat => bin("+"),
            PrimOp::FloatSub => bin("-"),
            PrimOp::FloatMul => bin("*"),
            PrimOp::FloatDiv => bin("/"),
            PrimOp::FloatRem => bin("%"),
            PrimOp::FloatNeg => format!("(-{})", a[0]),
            PrimOp::Not => format!("!{}", a[0]),
            PrimOp::Eq(t) => eq(t, false),
            PrimOp::Ne(t) => eq(t, true),
            PrimOp::Lt(t) => cmp(t, "<"),
            PrimOp::Le(t) => cmp(t, "<="),
            PrimOp::Gt(t) => cmp(t, ">"),
            PrimOp::Ge(t) => cmp(t, ">="),
            PrimOp::Schema(ty) => self.schema(ty),
            PrimOp::SchemaOf(ty, ids) => {
                let vars: Vec<(u32, String)> = ids.iter().copied().zip(a.iter().cloned()).collect();
                schema_with(self.cx.m, ty, &vars, true)
            }
            PrimOp::ShowWith => format!("$rt.show({}, {})", a[0], a[1]),
            PrimOp::Show(ty) => match ty {
                Ty::String => a[0].clone(),
                Ty::Int | Ty::Bool => format!("String({})", a[0]),
                Ty::Float => format!("$rt.showFloat({})", a[0]),
                _ => match self.schema(ty).as_str() {
                    "null" => format!("$rt.show({})", a[0]),
                    s => format!("$rt.show({}, {s})", a[0]),
                },
            },
        }
    }

    /// A pooled schema literal for `ty` (`null` stays inline).
    fn schema(&self, ty: &Ty) -> String {
        match schema_with(self.cx.m, ty, &[], true) {
            s if s == "null" || s.starts_with('"') => s,
            s => self.pool.get(s),
        }
    }
}

#[derive(Default)]
struct Frames {
    next: u32,
    def: HashMap<Label, u32>,
    jumps: HashMap<Label, Vec<u32>>,
    no_inline: HashSet<Label>,
}

impl Frames {
    fn fresh(&mut self) -> u32 {
        self.next += 1;
        self.next
    }
}

/// Every join point with its parameters, and whether it is jumped to from its own body.
fn collect_labels(e: &Expr, infos: &mut HashMap<Label, LabelInfo>, inside: &mut Vec<Label>) {
    sakura_core::ensure_stack(|| collect_labels_inner(e, infos, inside))
}

fn collect_labels_inner(e: &Expr, infos: &mut HashMap<Label, LabelInfo>, inside: &mut Vec<Label>) {
    match e {
        Expr::Let { body, .. } | Expr::Handle { body, .. } | Expr::Try { body, .. } => {
            collect_labels(body, infos, inside)
        }
        Expr::Ret(_) | Expr::Fail(_) => {}
        Expr::Jump(l, _) => {
            if inside.contains(l)
                && let Some(i) = infos.get_mut(l)
            {
                i.recursive = true;
            }
        }
        Expr::LetJoin {
            label,
            params,
            join,
            body,
        } => {
            infos.insert(
                *label,
                LabelInfo {
                    inline: true,
                    recursive: false,
                    params: params.clone(),
                },
            );
            inside.push(*label);
            collect_labels(join, infos, inside);
            inside.pop();
            collect_labels(body, infos, inside);
        }
        Expr::Switch { arms, default, .. } => {
            for (_, a) in arms {
                collect_labels(a, infos, inside);
            }
            if let Some(d) = default {
                collect_labels(d, infos, inside);
            }
        }
        Expr::If { then, els, .. } => {
            collect_labels(then, infos, inside);
            collect_labels(els, infos, inside);
        }
    }
}

/// Every `contract_enter` whose predicate cannot defect, and the `contract_exit`s that close
/// it, into `out`: such a bracket can never turn a defect into `D011` (design §17.115).
fn brackets(e: &Expr, proved: &[bool], out: &mut HashSet<Local>) {
    sakura_core::ensure_stack(|| match e {
        Expr::Let {
            local, bind, body, ..
        } => {
            if *bind == Bind::Call(Atom::Builtin("contract_enter".into()), vec![]) {
                let mut exits = Vec::new();
                if total_until_exit(body, proved, &mut exits) {
                    out.insert(*local);
                    out.extend(exits);
                }
            }
            brackets(body, proved, out)
        }
        Expr::Ret(_) | Expr::Jump(..) | Expr::Fail(_) => {}
        Expr::LetJoin { join, body, .. } => {
            brackets(join, proved, out);
            brackets(body, proved, out);
        }
        Expr::Switch { arms, default, .. } => {
            for (_, a) in arms {
                brackets(a, proved, out);
            }
            if let Some(d) = default {
                brackets(d, proved, out);
            }
        }
        Expr::If { then, els, .. } => {
            brackets(then, proved, out);
            brackets(els, proved, out);
        }
        Expr::Handle { body, .. } | Expr::Try { body, .. } => brackets(body, proved, out),
    })
}

/// Builtins that return for every argument of their type.
const TOTAL: &[&str] = &[
    "list_len",
    "map_len",
    "set_len",
    "string_len",
    "bytes_len",
    "list_get",
    "map_get",
    "list_contains",
    "map_contains",
    "set_contains",
    "string_contains",
    "string_starts_with",
    "string_ends_with",
    "int_min",
    "int_max",
    "int_abs",
    "int_to_float",
    "float_is_nan",
];

/// Does every path from `e` reach a `contract_exit` (collected in `exits`) without a bind that
/// may defect: a call other than a [`TOTAL`] builtin, unproved checked `Int` arithmetic, an
/// `Int` literal beyond ±(2^53−1), or anything but plain binds and branches?
fn total_until_exit(e: &Expr, proved: &[bool], exits: &mut Vec<Local>) -> bool {
    sakura_core::ensure_stack(|| match e {
        Expr::Let {
            local, bind, body, ..
        } => {
            if *bind == Bind::Call(Atom::Builtin("contract_exit".into()), vec![]) {
                exits.push(*local);
                return true;
            }
            let safe = |a: &Atom| !matches!(a, Atom::Lit(Lit::Int(i)) if lit_js(&Lit::Int(*i)).starts_with('$'));
            let ok = match bind {
                Bind::Atom(a) | Bind::Proj(a, _) => safe(a),
                Bind::Prim(op, args) => {
                    args.iter().all(safe)
                        && (proved[local.index()]
                            || !matches!(
                                op,
                                PrimOp::IntAdd
                                    | PrimOp::IntSub
                                    | PrimOp::IntMul
                                    | PrimOp::IntDiv
                                    | PrimOp::IntRem
                            ))
                }
                Bind::Alloc(_, args) => args.iter().all(safe),
                Bind::Call(Atom::Builtin(name), args) => {
                    TOTAL.contains(&name.as_str()) && args.iter().all(safe)
                }
                _ => false,
            };
            ok && total_until_exit(body, proved, exits)
        }
        Expr::Jump(..) => true,
        Expr::LetJoin { join, body, .. } => {
            total_until_exit(join, proved, exits) && total_until_exit(body, proved, exits)
        }
        Expr::Switch { arms, default, .. } => {
            arms.iter().all(|(_, a)| total_until_exit(a, proved, exits))
                && default
                    .as_ref()
                    .is_none_or(|d| total_until_exit(d, proved, exits))
        }
        Expr::If { then, els, .. } => {
            total_until_exit(then, proved, exits) && total_until_exit(els, proved, exits)
        }
        Expr::Ret(_) | Expr::Fail(_) | Expr::Handle { .. } | Expr::Try { .. } => false,
    })
}

/// How often each local is read in `e`.
fn count_uses(e: &Expr, out: &mut HashMap<Local, u32>) {
    sakura_core::ensure_stack(|| {
        let mut read = |a: &Atom| {
            if let Atom::Local(l) = a {
                *out.entry(*l).or_default() += 1;
            }
        };
        match e {
            Expr::Let { bind, body, .. } => {
                match bind {
                    Bind::Atom(a) | Bind::Check(_, a) | Bind::Proj(a, _) | Bind::StateGet(a, _) => {
                        read(a)
                    }
                    Bind::StateSet(a, _, v) => {
                        read(a);
                        read(v);
                    }
                    Bind::Prim(_, xs) | Bind::Closure(_, xs) | Bind::Alloc(_, xs) => {
                        xs.iter().for_each(read)
                    }
                    Bind::Call(f, xs) => {
                        read(f);
                        xs.iter().for_each(read);
                    }
                    Bind::Perform(_, _, xs) => xs.iter().for_each(read),
                    Bind::MakeHandler { state, clauses, .. } => {
                        state.iter().chain(clauses).for_each(read)
                    }
                    Bind::Hole(_) => {}
                }
                count_uses(body, out)
            }
            Expr::Ret(a) | Expr::Fail(a) => read(a),
            Expr::Jump(_, xs) => xs.iter().for_each(read),
            Expr::LetJoin { join, body, .. } => {
                count_uses(join, out);
                count_uses(body, out);
            }
            Expr::Switch {
                scrut,
                arms,
                default,
                ..
            } => {
                read(scrut);
                for (_, a) in arms {
                    count_uses(a, out);
                }
                if let Some(d) = default {
                    count_uses(d, out);
                }
            }
            Expr::If { cond, then, els } => {
                read(cond);
                count_uses(then, out);
                count_uses(els, out);
            }
            Expr::Handle { handler, body } => {
                read(handler);
                count_uses(body, out);
            }
            Expr::Try { body, .. } => count_uses(body, out),
        }
    })
}

fn lit_js(lit: &Lit) -> String {
    const SAFE: i64 = (1 << 53) - 1;
    match lit {
        Lit::Unit => "undefined".into(),
        Lit::Bool(b) => b.to_string(),
        Lit::Int(i) if (-SAFE..=SAFE).contains(i) => i.to_string(),
        Lit::Int(i) => format!("$rt.unsafeInt(\"{i}\")"),
        Lit::Float(f) if f.is_nan() => "NaN".into(),
        Lit::Float(f) if f.is_infinite() => if *f > 0.0 { "Infinity" } else { "-Infinity" }.into(),
        Lit::Float(f) => format!("{f:?}"),
        Lit::String(s) => js_string(s),
    }
}
